// Venue display short link: hightopchallenge.com/tv/<code>
// (docs/live-trivia-pregame-and-display-cleanup-plan.md, Phase 4).
//
// Pure and client-safe. The code itself is generated by the database
// (supabase/migrations/20261114190044_venue_display_code.sql); its alphabet is
// copied here and pinned by tests/display-code-contract.test.ts.

import { apexHost, marketingUrl } from "@/lib/domainSplit";

/** Crockford base32: 0-9 A-Z minus I L O U. */
export const DISPLAY_CODE_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
export const DISPLAY_CODE_LENGTH = 4;
const DISPLAY_CODE_PATTERN = /^[0-9A-HJKMNP-TV-Z]{4}$/;

/** Uppercase and drop spaces/hyphens. Does not validate. */
export const normalizeDisplayCode = (input: string): string =>
  String(input ?? "").toUpperCase().replace(/[\s-]/g, "");

/** A normalized, well-formed code, or null. */
export const parseDisplayCode = (input: string): string | null => {
  const code = normalizeDisplayCode(input);
  return DISPLAY_CODE_PATTERN.test(code) ? code : null;
};

export const displayCodePath = (code: string): string => `/tv/${code}`;

/** The full link to copy or paste, e.g. `https://hightopchallenge.com/tv/K7M2`. */
export const displayShortUrl = (code: string): string => marketingUrl(displayCodePath(code));

/** The link as shown on screen, e.g. `hightopchallenge.com/tv/K7M2`. */
export const displayShortUrlLabel = (code: string): string => `${apexHost()}${displayCodePath(code)}`;
